export default ({root,scope,listen,observe}) => {
  const key='rainlab.session.v1';
  const q=s=>root.querySelector(s);
  const txt=(s,v)=>{const el=q(s);if(el)el.textContent=String(v);};
  const clean=n=>Math.round(n*1000000)/1000000;
  const fmt=n=>String(clean(n));
  const calc=(P,f,I)=>{const total=P*100;const infil=clean((1-f)*Math.min(P,I)*100);return {total,infil,runoff:clean(total-infil)};};
  const get=()=>scope.state.get(key)||{};
  const draft=s=>s.draft||{P:30,percent:60,I:20};
  function paint(s){s=s||{};const d=draft(s),f=d.percent/100,c=calc(d.P,f,d.I);
    for(const [sel,v] of [['#rain-p',d.P],['#rain-f',d.percent],['#rain-i',d.I]])if(q(sel))q(sel).value=String(v);
    txt('#p-out',d.P);txt('#f-out',d.percent);txt('#i-out',d.I);
    txt('#total',fmt(c.total));txt('#infil',fmt(c.infil));txt('#runoff',fmt(c.runoff));
    const pct=c.total?c.infil/c.total*100:0;
    q('#bar-in').style.width=pct+'%';q('#bar-run').style.width=(c.total?100-pct:0)+'%';
    txt('#in-pct',c.total?pct.toFixed(1)+'%':'—');txt('#run-pct',c.total?(100-pct).toFixed(1)+'%':'—');
    txt('#formula',`(1−${fmt(f)}) × min(${d.P},${d.I}) × 100 = ${fmt(c.infil)} 升`);
    txt('#why',`未硬化区域 ${fmt(100-d.percent)} 平方米，每平方米本次吸入 ${Math.min(d.P,d.I)} 升。${d.P===0?'没有降雨，水量均为0。':d.I>=d.P?'雨量限制了入渗，继续提高 I 暂无收益。':d.percent===100?'全部硬化，本模型中不能入渗。':'土壤上限限制了入渗。'}`);
    const rows=s.records||[],last=rows[rows.length-1];
    txt('#record-status',last?`已记录 ${s.count||rows.length} 条；${last.P===d.P&&last.f===f&&last.I===d.I?'当前对应最近记录 #'+last.id:'当前修改尚未记录'}。`:s.touched?'当前试算尚未记录。':'示例预览，尚未记录。');
  }
  listen('input','input[type=range]',()=>{const s=get();scope.state.set(key,{...s,touched:true,draft:{P:Number(q('#rain-p').value),percent:Number(q('#rain-f').value),I:Number(q('#rain-i').value)}});});
  listen('click','#record',()=>{const s=get(),d=draft(s),f=d.percent/100,id=(s.count||0)+1;const record={id,P:d.P,f,I:d.I,...calc(d.P,f,d.I)};scope.state.set(key,{...s,count:id,records:[...(s.records||[]).slice(-11),record],proposal:null});});
  observe(key,paint);
};
